 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Extend upward from colored markers only to the same number of cells
    # represented by the marker's horizontal run of 1s on either side.
    for r, row in enumerate(grid):
        if any(row):
            for c, value in enumerate(row):
                if value not in (2, 8):
                    continue
                left = c - 1
                while left >= 0 and row[left] == 1:
                    left -= 1
                right = c + 1
                while right < len(row) and row[right] == 1:
                    right += 1
                distance = max(c - left - 1, right - c - 1)
                # Fill the vertical ray with color, limited to available rows.
                for rr in range(max(0, r - distance), r):
                    out[rr][c] = value
                # Short continuation below the bar as shown by the examples.
                for rr in range(r + 1, min(len(grid), r + 1 + distance)):
                    out[rr][c] = value
    return out
